// ratelimit.go
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time so tests can control the rate limiter.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token-bucket rate limiter.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// New creates a full bucket. capacity must be > 0, rate must be > 0,
// and clock must be non-nil (pass nil to use the system clock).
func New(capacity int, rate float64, clock Clock) (*TokenBucket, error) {
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be > 0")
	}
	if rate <= 0 || math.IsNaN(rate) || math.IsInf(rate, 0) {
		return nil, errors.New("ratelimit: rate must be finite and > 0")
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &TokenBucket{
		capacity: float64(capacity),
		tokens:   float64(capacity),
		rate:     rate,
		last:     now,
		clock:    clock,
	}, nil
}

// Allow reports whether a single token is available.
func (b *TokenBucket) Allow() bool { return b.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// n <= 0 is always allowed. n > capacity is never allowed.
func (b *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	if float64(n) > b.capacity || float64(n) > b.tokens {
		return false
	}
	b.tokens -= float64(n)
	return true
}

func (b *TokenBucket) refillLocked() {
	now := b.clock.Now()
	if now.Before(b.last) {
		return // clock moved backwards; do not refill or move last
	}
	elapsed := now.Sub(b.last)
	if elapsed <= 0 {
		return
	}
	b.tokens = math.Min(b.capacity, b.tokens+elapsed.Seconds()*b.rate)
	b.last = now
}
