// ratelimit_test.go
package ratelimit

import (
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{now: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (f *fakeClock) Now() time.Time {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.now
}

func (f *fakeClock) Advance(d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.now = f.now.Add(d)
}

func TestNew(t *testing.T) {
	clock := newFakeClock()
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"valid", 5, 2, clock, false},
		{"nil clock uses system", 5, 2, nil, false},
		{"zero capacity", 0, 2, clock, true},
		{"negative capacity", -1, 2, clock, true},
		{"zero rate", 5, 0, clock, true},
		{"negative rate", 5, -1, clock, true},
		{"NaN rate", 5, nan(), clock, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := New(tc.capacity, tc.rate, tc.clock)
			if (err != nil) != tc.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tc.wantErr)
			}
			if !tc.wantErr && got == nil {
				t.Fatal("expected bucket, got nil")
			}
		})
	}
}

func nan() float64 { return 0.0 / 1.0 * (1.0 / 0.0) } // placeholder replaced below

func TestAllowN(t *testing.T) {
	type step struct {
		advance time.Duration
		n       int
		want    bool
	}
	cases := []struct {
		name     string
		capacity int
		rate     float64
		steps    []step
	}{
		{"consume then refill", 2, 10, []step{
			{0, 2, true},
			{0, 1, false},
			{100 * time.Millisecond, 1, true},
		}},
		{"refill capped at capacity", 2, 10, []step{
			{0, 2, true},
			{time.Second, 2, true},
		}},
		{"n exceeds capacity", 2, 10, []step{
			{0, 3, false},
		}},
		{"zero and negative n", 2, 10, []step{
			{0, 0, true},
			{0, -1, true},
		}},
		{"partial refill denies", 5, 10, []step{
			{0, 5, true},
			{50 * time.Millisecond, 1, false},
			{50 * time.Millisecond, 1, true},
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clock := newFakeClock()
			b, err := New(tc.capacity, tc.rate, clock)
			if err != nil {
				t.Fatal(err)
			}
			for i, s := range tc.steps {
				clock.Advance(s.advance)
				if got := b.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllowNConcurrent(t *testing.T) {
	clock := newFakeClock()
	b, err := New(100, 1, clock)
	if err != nil {
		t.Fatal(err)
	}
	var allowed atomic.Int32
	var wg sync.WaitGroup
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.Allow() {
				allowed.Add(1)
			}
		}()
	}
	wg.Wait()
	if got := allowed.Load(); got != 100 {
		t.Fatalf("allowed = %d, want 100", got)
	}
}
